function s(n: number) : string {
    let r : string = ""
    for (let i : number = n; i >= 0; i--) {
        if (i > 4 && i < 7) {
            r = r + (i - 1)
        } else if (i < 7) {
            r = (i + 1)  + r
        } else {
            r = r + i
        }
    }
    return r
}

